<template><div class="page-card"><h2>图书管理</h2><div class="toolbar"><el-input v-model="keyword" placeholder="书名/作者/ISBN" clearable @keyup.enter="load" style="width:240px"/><el-button type="primary" @click="load">查询</el-button><el-button v-if="isAdmin" type="success" @click="open()">新增图书</el-button></div><el-table :data="rows" stripe><el-table-column prop="isbn" label="ISBN"/><el-table-column prop="title" label="书名"/><el-table-column prop="author" label="作者"/><el-table-column prop="categoryName" label="分类"/><el-table-column prop="totalStock" label="总库存"/><el-table-column prop="availableStock" label="可借"/><el-table-column label="操作" v-if="isAdmin"><template #default="scope"><el-button link @click="open(scope.row)">编辑</el-button></template></el-table-column></el-table><el-pagination layout="prev,pager,next" :total="total" v-model:current-page="page" @current-change="load"/></div><el-dialog v-model="visible" title="图书信息"><el-form :model="form"><el-form-item label="ISBN"><el-input v-model="form.isbn"/></el-form-item><el-form-item label="书名"><el-input v-model="form.title"/></el-form-item><el-form-item label="作者"><el-input v-model="form.author"/></el-form-item><el-form-item label="分类"><el-select v-model="form.categoryId"><el-option v-for="c in categories" :key="c.id" :label="c.name" :value="c.id"/></el-select></el-form-item><el-form-item label="库存"><el-input-number v-model="form.totalStock"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></template>
<script setup>import {ref,reactive,computed,onMounted} from 'vue';import {ElMessage} from 'element-plus';import http from '../api/http';const user=JSON.parse(localStorage.getItem('library_user')||'null');const isAdmin=computed(()=>user?.role==='ADMIN');const rows=ref([]),categories=ref([]),total=ref(0),page=ref(1),keyword=ref(''),visible=ref(false);const form=reactive({});async function load(){const r=await http.get('/books',{params:{page:page.value,size:10,keyword:keyword.value}});rows.value=r.data.records;total.value=r.data.total}function open(row){Object.assign(form,row||{isbn:'',title:'',author:'',categoryId:null,totalStock:0});visible.value=true}async function save(){const r=form.id?await http.put('/books',form):await http.post('/books',form);if(r.code===200){visible.value=false;ElMessage.success('保存成功');load()}}onMounted(async()=>{load();const r=await http.get('/categories');categories.value=r.data})</script>
